  "title": "Rotated Bounding Box Intersection Area",
  "difficulty": "medium",
  "category": "boxes_transforms",
  "problem": "Implement a function to compute the intersection area between two rotated bounding boxes. Each box is defined by its center coordinates (cx, cy), width (w), height (h), and rotation angle (theta) in radians. The rotation is counter-clockwise around the center. The intersection area is the area of the polygon formed by the overlap of the two rectangles. If the boxes do not intersect, return 0.0. Use the Sutherland-Hodgman algorithm for polygon clipping.",
  "requirements": [
    "Input boxes are tuples/lists of (cx, cy, w, h, theta).",
    "Theta is in radians.",
    "Return the intersection area as a float.",
    "Handle cases where one box is completely inside the other.",
    "Handle cases where boxes do not intersect.",
    "Use standard Python libraries (math, numpy allowed)."
  ],
  "function_signature": "def rotated_box_intersection(box1: tuple, box2: tuple) -> float:",
  "public_examples": [
    {
      "input": "box1 = (0, 0, 2, 2, 0)
box2 = (1, 0, 2, 2, 0)",
      "output": "1.0"
    },
    {
      "input": "box1 = (0, 0, 2, 2, 0)
box2 = (0, 0, 2, 2, 0)",
      "output": "4.0"
    },
    {
      "input": "box1 = (0, 0, 2, 2, 0)
box2 = (5, 5, 2, 2, 0)",
      "output": "0.0"
    }
  ],
  "reference_answer": "import math
import numpy as np

def get_corners(cx, cy, w, h, theta):
    cos_t = math.cos(theta)
    sin_t = math.sin(theta)
    hw, hh = w / 2.0, h / 2.0
    corners = [
        (cx + hw * cos_t - hh * sin_t, cy + hw * sin_t + hh * cos_t),
        (cx - hw * cos_t - hh * sin_t, cy - hw * sin_t + hh * cos_t),
        (cx - hw * cos_t + hh * sin_t, cy - hw * sin_t - hh * cos_t),
        (cx + hw * cos_t + hh * sin_t, cy + hw * sin_t - hh * cos_t)
    ]
    return np.array(corners)

def polygon_area(pts):
    if len(pts) < 3:
        return 0.0
    x = pts[:, 0]
    y = pts[:, 1]
    return 0.5 * abs(np.dot(x, np.roll(y, 1)) - np.dot(y, np.roll(x, 1)))

def clip_polygon(subject_poly, clip_poly):
    def inside(p, a, b):
        return (b[0] - a[0]) * (p[1] - a[1]) - (b[1] - a[1]) * (p[0] - a[0]) >= 0

    def intersection(p1, p2, a, b):
        x1, y1 = p1
        x2, y2 = p2
        x3, y3 = a
        x4, y4 = b
        den = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4)
        if abs(den) < 1e-9:
            return p1
        t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / den
        return (x1 + t * (x2 - x1), y1 + t * (y2 - y1))

    output_poly = list(subject_poly)
    if not output_poly:
        return []

    for i in range(len(clip_poly)):
        input_poly = output_poly
        output_poly = []
        if not input_poly:
            break

        a = clip_poly[i]
        b = clip_poly[(i + 1) % len(clip_poly)]

        s = input_poly[-1]
        for e in input_poly:
            if inside(e, a, b):
                if not inside(s, a, b):
                    output_poly.append(intersection(s, e, a, b))
                output_poly.append(e)
            elif inside(s, a, b):
                output_poly.append(intersection(s, e, a, b))
            s = e
    return output_poly

def rotated_box_intersection(box1, box2):
    corners1 = get_corners(*box1)
    corners2 = get_corners(*box2)

    # Ensure counter-clockwise order for Sutherland-Hodgman
    # Check orientation of corners1
    area1 = polygon_area(corners1)
    if area1 < 0:
        corners1 = corners1[::-1]

    area2 = polygon_area(corners2)
    if area2 < 0:
        corners2 = corners2[::-1]

    # Clip corners1 by corners2
    clipped = clip_polygon(corners1, corners2)
    if not clipped:
        return 0.0

    return polygon_area(np.array(clipped))",
