    "assert abs(rotated_box_intersection((0,0,2,2,0), (1,0,2,2,0)) - 1.0) < 1e-5",
    "assert abs(rotated_box_intersection((0,0,2,2,0), (0,0,2,2,0)) - 4.0) < 1e-5",
    "assert abs(rotated_box_intersection((0,0,2,2,0), (5,5,2,2,0)) - 0.0) < 1e-5",
    "assert abs(rotated_box_intersection((0,0,2,2,math.pi/4), (0,0,2,2,0)) - (4 - 2*(2-math.sqrt(2))**2/2)) < 1e-4",
    "assert abs(rotated_box_intersection((0,0,4,2,0), (0,0,2,4,0)) - 4.0) < 1e-5",
    "assert abs(rotated_box_intersection((0,0,2,2,0), (0,0,1,1,0)) - 1.0) < 1e-5",
    "assert abs(rotated_box_intersection((0,0,2,2,0), (0,0,3,3,0)) - 4.0) < 1e-5"
  ]
